def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    factors = []
    primes = set()
    for x in arr:
        z = x
        fs = []
        p = 2
        while p * p <= z:
            if z % p == 0:
                e = 0
                while z % p == 0:
                    z //= p
                    e += 1
                fs.append((p, e))
                primes.add(p)
            p += 1 if p == 2 else 2
        if z > 1:
            fs.append((z, 1))
            primes.add(z)
        factors.append(dict(fs))

    answer = 1
    for prime in primes:
        exponents = [f.get(prime, 0) for f in factors]
        max_height = sum(exponents)
        max_e = max(exponents, default=0)
        powers = [1] * (max(n * max_e, max_height) + 1)
        for k in range(1, len(powers)):
            powers[k] = powers[k - 1] * prime % MOD

        dp = {0: 1}
        for i, e in enumerate(exponents):
            nd = {}
            if e:
                for y, value in dp.items():
                    ny = y + e
                    if ny >= 0:
                        w = value * powers[ny] % MOD
                    else:
                        d = -ny
                        ny = 0
                        w = value * powers[d * (i + 1)] % MOD
                    nd[ny] = (nd.get(ny, 0) + w) % MOD

                    ny = y - e
                    if ny >= 0:
                        w = value * powers[ny] % MOD
                    else:
                        d = -ny
                        ny = 0
                        w = value * powers[d * (i + 1)] % MOD
                    nd[ny] = (nd.get(ny, 0) + w) % MOD
            else:
                for y, value in dp.items():
                    nd[y] = value * powers[y] % MOD
            dp = nd
        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

