def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]
    m = max(a)
    spf = [0] * (m + 1)
    for i in range(2, m + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= m:
                for j in range(i * i, m + 1, i):
                    if spf[j] == 0:
                        spf[j] = i
    omega = [0] * (m + 1)
    for x in range(2, m + 1):
        omega[x] = omega[x // spf[x]] + 1
    nim = 0
    for x in a:
        nim ^= omega[x]
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

