from array import array
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); q = next(it)
    parent = array('i', range(n))
    lo = array('i', range(n))
    hi = array('i', range(n))
    color = array('i', range(1, n + 1))
    count = array('i', [0]) + array('i', [1]) * n

    def find(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != x:
            y = parent[x]
            parent[x] = r
            x = y
        return r

    def unite(a, b):
        a = find(a); b = find(b)
        if a == b:
            return a
        sa = hi[a] - lo[a] + 1
        sb = hi[b] - lo[b] + 1
        if sa < sb:
            a, b = b, a
        parent[b] = a
        if lo[b] < lo[a]:
            lo[a] = lo[b]
        if hi[b] > hi[a]:
            hi[a] = hi[b]
        return a

    out = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            x = next(it) - 1
            c = next(it)
            r = find(x)
            old = color[r]
            if old != c:
                length = hi[r] - lo[r] + 1
                count[old] -= length
                count[c] += length
                color[r] = c
            if lo[r] > 0:
                lroot = find(lo[r] - 1)
                if color[lroot] == c:
                    r = unite(r, lroot)
            if hi[r] + 1 < n:
                rroot = find(hi[r] + 1)
                if color[rroot] == c:
                    r = unite(r, rroot)
        else:
            c = next(it)
            out.append(str(count[c]))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        largest = second = count_largest = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in by_right[r]:
                if a > largest:
                    second = largest
                    largest = a
                    count_largest = 1
                    largest_id = i
                elif a == largest:
                    count_largest += 1
                elif a > second:
                    second = a

            base += r - largest
            if count_largest == 1:
                gain[largest_id] += largest - second

        return base + max(gain)

