import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    roads = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        roads.append((a - 1, b - 1, c))

    queries = []
    closed = set()
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            idx = z[1] - 1
            closed.add(idx)
            queries.append((1, idx))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    inf = 10**30
    dist = [[inf] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for idx, (a, b, c) in enumerate(roads):
        if idx not in closed:
            dist[a][b] = dist[b][a] = c

    # Initial all-pairs shortest paths after all deletions.
    for k in range(N):
        dk = dist[k]
        for i in range(N):
            di = dist[i]
            dik = di[k]
            if dik == inf:
                continue
            for j in range(N):
                candidate = dik + dk[j]
                if candidate < di[j]:
                    di[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(value if value < inf else -1))
        else:
            a, b, weight = roads[query[1]]
            # Adding one edge can improve a shortest path by using it once.
            # Save the old distances to its endpoints before updating the matrix.
            to_a = [dist[i][a] for i in range(N)]
            to_b = [dist[i][b] for i in range(N)]
            for i in range(N):
                row = dist[i]
                for j in range(i, N):
                    candidate = min(
                        row[j],
                        to_a[i] + weight + to_b[j],
                        to_b[i] + weight + to_a[j],
                    )
                    if candidate < row[j]:
                        row[j] = candidate
                        dist[j][i] = candidate

    print("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

