import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    items = []
    for i in range(n):
        a, p, b, q = data[2 + 4 * i: 6 + 4 * i]
        period = b // math.gcd(a, b)
        items.append((a, p, b, q, period))

    def feasible(capacity):
        total = 0
        for a, p, b, q, period in items:
            max_s = (capacity + a - 1) // a
            best = 10**30
            # Within a fixed residue modulo period, the cost changes linearly
            # as the number of S machines increases by period. Thus a minimum
            # occurs at one of the two endpoints of the feasible range.
            for residue in range(min(period, max_s + 1)):
                high = residue + ((max_s - residue) // period) * period
                for count_s in (residue, high):
                    count_t = max(0, (capacity - a * count_s + b - 1) // b)
                    cost = count_s * p + count_t * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

