from math import comb

MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        counts = [0] * (n + 1)
        prefix_ones = 0

        # At each 1 in s, choose 0 at this position to form a smaller number;
        # the remaining suffix can have any number of set bits.
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    total_ones = prefix_ones + suffix_ones
                    counts[total_ones] = (counts[total_ones] + comb(remaining, suffix_ones)) % MOD
                prefix_ones += 1

        answer = 0
        for ones in range(1, n + 1):
            value = ones
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1

            # An integer with `ones` set bits takes one operation to reach
            # `ones`, then `steps` more operations to reach 1.
            if steps + 1 <= k:
                answer = (answer + counts[ones]) % MOD

        return answer

