def solve():
 d=list(map(int,sys.stdin.buffer.read().split()))
 if not d:return
 it=iter(d); N=next(it); M=next(it); Q=next(it)
 people=[(next(it),next(it)) for _ in range(M)]
 queries=[(next(it),next(it)) for _ in range(Q)]
 out=[]
 for L,R in queries:
  par=list(range(N+1))
  def find(x):
