  adj=[[] for _ in range(N+1)]; indeg=[0]*(N+1); strict=[]
  for i in range(L-1,R):
   a,b=people[i]; lo=min(a,b); hi=max(a,b); u=find(a)
   if a<b:
    for x in range(lo+1,hi):
     v=find(x); adj[u].append(v); indeg[v]+=1; strict.append((u,v))
   else:
    for x in range(lo+1,hi):
     v=find(x); adj[v].append(u); indeg[u]+=1; strict.append((v,u))
  # Collapse equality reps; strict self-loop is impossible
  if any(u==v for u,v in strict):
   out.append('No'); continue
  # topo all reps, any directed cycle means impossible
  reps=set(find(x) for x in range(1,N+1))
  stack=[x for x in reps if indeg[x]==0]; seen=0
  while stack:
   u=stack.pop(); seen+=1
   for v in adj[u]:
    indeg[v]-=1
    if indeg[v]==0: stack.append(v)
  out.append('Yes' if seen==len(reps) else 'No')
