import sys

def main():
    z=list(map(int,sys.stdin.buffer.read().split()))
    n=z[0]; A=z[1:]
    limit=(1<<100)-A[-1]-1
    if limit<1:
        print(0); return
    ans=0
    def score(i):
        total=0
        for a in A:
            x=i+a
            t=(x & -x).bit_length()-1
            # In the regular paper-folding sequence, the fold direction
            # is determined by the two bits following the least significant 1.
            if ((x >> (t+1)) & 1)==0:
                total+=1
        return total
    def consider(res, modulus):
        nonlocal ans
        i=res
        if i<1:
            i += ((1-i+modulus-1)//modulus)*modulus
        if i<=limit:
            ans=max(ans,score(i))
    def visit(res, depth):
        if depth==100:
            return
        modulus=1 << (depth+1)
        targets={(-a) % modulus for a in A}
        for bit in (0,1):
            child=res+(bit << depth)
            if child in targets:
                visit(child,depth+1)
            else:
                consider(child,modulus)
    visit(0,0)
    print(ans)

if __name__=='__main__':
    main()

