import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    rows = [0] * n
    for _ in range(m):
        u = next(it) - 1
        v = next(it) - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [col for col in range(n) if col not in pivot_set]
    # A basis for the nullspace; each vector is encoded as a bitmask.
    basis = []
    for free in free_cols:
        vec = 1 << free
        for row, pivot in enumerate(pivots):
            if (rows[row] >> free) & 1:
                vec |= 1 << pivot
        basis.append(vec)

    # Use a separate output bit for each nullspace basis vector.
    # Shift by two for nonempty graphs when the 60-bit limit allows it.
    offset = 2 if m and len(basis) <= 58 else 0
    values = [0] * n
    for k, vec in enumerate(basis):
        bit = 1 << (k + offset)
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= bit

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

