N = int(input())

# Let d = x - y. Then
# N = d * (3*y*y + 3*d*y + d*d), and d^3 <= N.
for d in range(1, 1_000_001):
    if N % d:
        continue

    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue

    root = math.isqrt(disc)
    if root * root != disc:
        continue

    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        print(y + d, y)
        break
else:
    print(-1)

