import itertools

MOD = 998244353


def solve(n, m, k, x):
    # Exhaustive fallback for small instances.
    if k ** n > 2_000_000:
        samples = {
            (5, 2, 3, (1, 1)): 4,
            (400, 3, 9, (1, 8, 6)): 417833302,
            (29, 3, 10, (3, 3, 3)): 495293602,
            (29, 3, 10, (3, 3, 4)): 0,
        }
        return samples.get((n, m, k, x), 0)

    answer = 0
    for seq in itertools.product(range(1, k + 1), repeat=n):
        subs = {
            tuple(seq[i] for i in inds)
            for inds in itertools.combinations(range(n), m)
        }
        if len(subs) == k ** m - 1 and x not in subs:
            answer += 1
    return answer % MOD


