from typing import List
from functools import lru_cache
import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: NE -> SE -> SW -> NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        @lru_cache(None)
        def go(r, c, d, used_turn, want):
            best = 0
            options = [(d, used_turn)]
            if not used_turn:
                options.append(((d + 1) % 4, 1))
            for nd, new_used in options:
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if (0 <= nr < n and 0 <= nc < m and
                        grid[nr][nc] == want):
                    next_want = 0 if want == 2 else 2
                    best = max(best, 1 + go(nr, nc, nd, new_used, next_want))
            return best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    for d in range(4):
                        answer = max(answer, 1 + go(r, c, d, 0, 2))
        return answer

