from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        total = 0
        for first in (1, 0):
            slots_odd = (n + (1 if first else 0)) // 2
            slots_even = n - slots_odd
            if len(odds) == slots_odd and len(evens) == slots_even:
                total += factorial(len(odds)) * factorial(len(evens))
        if k > total:
            return []
        out = []
        prev_parity = None
        while len(out) < n:
            for x in range(1, n + 1):
                if x in out:
                    continue
                p = x & 1
                if prev_parity is not None and p == prev_parity:
                    continue
                ro = len(odds) - (p == 1)
                re = len(evens) - (p == 0)
                remaining = n - len(out) - 1
                need_first = 1 - p
                need_odd_slots = (remaining + (1 if need_first == 1 else 0)) // 2
                need_even_slots = remaining - need_odd_slots
                if ro == need_odd_slots and re == need_even_slots:
                    ways = factorial(ro) * factorial(re)
                else:
                    ways = 0
                if k > ways:
                    k -= ways
                else:
                    out.append(x)
                    if p == 1:
                        odds.remove(x)
                    else:
                        evens.remove(x)
                    prev_parity = p
                    break
            else:
                return []
        return out

