class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for j in range(m):
            a = pow(10, n - 1 - j, k)
            b = pow(10, j, k)
            weights.append(a if j == n - 1 - j else (a + b) % k)

        can = [[False] * k for _ in range(m + 1)]
        can[m][0] = True
        for i in range(m - 1, -1, -1):
            w = weights[i]
            nxt = can[i + 1]
            cur = can[i]
            for r in range(k):
                cur[r] = any(nxt[(r - d * w) % k] for d in range(10))

        digits = []
        residue = 0
        for i, w in enumerate(weights):
            for d in range(9 if i == 0 else 9, 0 if i == 0 else -1, -1):
                nr = (residue + d * w) % k
                if can[i + 1][(-nr) % k]:
                    digits.append(str(d))
                    residue = nr
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

