from typing import List
from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        levels = n.bit_length()
        jump = [array('i', nxt)]
        aggregate = [array(
            'q',
            (nums[i] * (nxt[i] - i) - (prefix[nxt[i]] - prefix[i])
             for i in range(n))
        )]

        for _ in range(1, levels):
            previous_jump = jump[-1]
            previous_aggregate = aggregate[-1]
            current_jump = array('i', [n]) * n
            current_aggregate = array('q', [0]) * n
            for i in range(n):
                middle = previous_jump[i]
                current_aggregate[i] = previous_aggregate[i] + (
                    previous_aggregate[middle] if middle < n else 0
                )
                current_jump[i] = previous_jump[middle] if middle < n else n
            jump.append(current_jump)
            aggregate.append(current_aggregate)

        def cost(start: int, limit: int) -> int:
            position = start
            result = 0
            for level in range(levels - 1, -1, -1):
                if position >= limit:
                    break
                end = jump[level][position]
                if end <= limit and end > position:
                    result += aggregate[level][position]
                    position = end
            if position < limit:
                result += nums[position] * (limit - position) - (
                    prefix[limit] - prefix[position]
                )
            return result

        answer = 0
        for left in range(n):
            low, high = left, n
            while low < high:
                middle = (low + high + 1) // 2
                if cost(left, middle) <= k:
                    low = middle
                else:
                    high = middle - 1
            answer += low - left
        return answer

