import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, len(data), 2)]

    # For an outer function i and inner function j, i is preferable iff
    # (A_i - 1) / B_i >= (A_j - 1) / B_j. Thus ascending ratios give
    # the canonical inner-to-outer order.
    funcs.sort(key=lambda f: (f[0] - 1) / f[1])

    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for chosen in range(k, 0, -1):
            previous = dp[chosen - 1]
            if previous is not None:
                value = a * previous + b
                if dp[chosen] is None or value > dp[chosen]:
                    dp[chosen] = value
    print(dp[k])

if __name__ == '__main__':
    main()

