class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        c = [0] * 26
        for ch in s:
            c[ord(ch) - 97] += 1
        ans = len(s)
        for k in range(1, max(c) + 1):
            dp = {0: 0}
            for i in range(26):
                nd = {}
                for carry, cost in dp.items():
                    total = c[i] + carry
                    for keep in (0, k):
                        # Any surplus may be deleted or passed to the next letter.
                        surplus = max(0, total - keep)
                        for out in range(surplus + 1):
                            if i == 25 and out:
                                continue
                            val = cost + abs(total - keep - out) + out
                            if val < nd.get(out, 10**9):
                                nd[out] = val
                dp = nd
            ans = min(ans, dp.get(0, 10**9))
        return ans

