class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        c = [0]*26
        for x in s: c[ord(x)-97]+=1
        ans=len(s)
        for k in range(1,max(c)+1):
            # dp over letters with amount carried from previous letter
            dp={0:0}
            for i in range(26):
                nd={}
                for carry,cost in dp.items():
                    total=c[i]+carry
                    # Final count zero; or exactly k. Carry surplus forward,
                    # with insertion/deletion to select the retained count.
                    for keep in (0,k):
                        for out in (0,max(0,total-keep)):
                            v=cost+abs(total-keep-out)+out
                            nd[out]=min(nd.get(out,10**9),v)
                dp=nd
            ans=min(ans,min(dp.values()))
        return ans

