import sys
MOD=998244353

def solve_case(H,W,grid):
    # Transfer across rows. The frontier consists of the vertical edge mask.
    # For a fixed incoming mask, process one row while retaining its outgoing mask
    # and the horizontal edge at the left boundary.
    if W>20:
        # Transpose so the exponential dimension is the smaller one.
        grid=[''.join(grid[i][j] for i in range(H)) for j in range(W)]
        H,W=W,H
    N=1<<W
    states=[]
    for row in grid:
        trans=[]
        for top in range(N):
            # State (bottom mask, first horizontal bit, current horizontal bit)
            dp={(0,0,0):1,(0,1,1):1}
            for j,ch in enumerate(row):
                nd={}
                t=(top>>j)&1
                for (bm,first,left),ways in dp.items():
                    for right in (0,1):
                        for bot in (0,1):
                            bits=(left,right,t,bot)
                            if sum(bits)!=2: continue
                            # A: one horizontal and one vertical edge; B: opposite pair
                            if ch=='A':
                                if left+right!=1 or t+bot!=1: continue
                            else:
                                if not ((left==right and t==bot and left!=t)): continue
                            key=(bm|(bot<<j),first,right)
                            nd[key]=(nd.get(key,0)+ways)%MOD
                dp=nd
            out={}
            for (bm,first,last),v in dp.items():
                if last==first: out[bm]=(out.get(bm,0)+v)%MOD
            trans.append(out)
        states.append(trans)
    ans=0
    # Close the vertical direction by fixing the initial frontier.
    for start in range(N):
        dp={start:1}
        for r in range(H):
            nd={}
            tr=states[r]
            for mask,v in dp.items():
                for nxt,c in tr[mask].items():
                    nd[nxt]=(nd.get(nxt,0)+v*c)%MOD
            dp=nd
            if not dp: break
        ans=(ans+dp.get(start,0))%MOD
    return ans

