class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            m = len(t)
            found = [False] * (n + 1)
            if m == 0:
                return found
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    found[i - m + 1] = True
                    j = pi[j - 1]
            return found

        def next_positions(t):
            found = occurrences(t)
            nxt = [n + 1] * (n + 1)
            nearest = n + 1
            for i in range(n, -1, -1):
                if found[i]:
                    nearest = i
                nxt[i] = nearest
            return nxt

        occ_a = occurrences(a)
        next_b = next_positions(b) if b else None
        next_c = next_positions(c) if c else None
        ans = n + 1
        for start in range(n + 1):
            if a:
                if start + len(a) > n or not occ_a[start]:
                    continue
                pos = start + len(a)
            else:
                pos = start
            if b:
                pos = next_b[pos] if pos <= n else n + 1
                if pos > n:
                    continue
                pos += len(b)
            if c:
                pos = next_c[pos] if pos <= n else n + 1
                if pos > n:
                    continue
                pos += len(c)
            if pos <= n:
                ans = min(ans, pos - start)
        return -1 if ans == n + 1 else ans

