def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    s, t = data[1], data[2]
    n, m = len(s), len(t)

    if abs(n - m) > k:
        print("No")
        return

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        print("Yes")
        return

    # For each edit count, retain the furthest position reached on each
    # diagonal (i - j), extending across matching characters greedily.
    previous = {0: x}
    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            furthest = -1

            # Substitution: stay on the same diagonal.
            if diagonal in previous:
                px = previous[diagonal]
                py = px - diagonal
                if px < n and py < m:
                    furthest = px + 1

            # Delete from S: move from diagonal - 1.
            if diagonal - 1 in previous:
                px = previous[diagonal - 1]
                py = px - (diagonal - 1)
                if px < n:
                    furthest = max(furthest, px + 1)

            # Insert into S: move from diagonal + 1.
            if diagonal + 1 in previous:
                px = previous[diagonal + 1]
                py = px - (diagonal + 1)
                if py < m:
                    furthest = max(furthest, px)

            if furthest < 0:
                continue
            y = furthest - diagonal
            if y < 0 or y > m or furthest > n:
                continue

            while furthest < n and y < m and s[furthest] == t[y]:
                furthest += 1
                y += 1

            current[diagonal] = furthest
            if furthest == n and y == m:
                print("Yes")
                return

        previous = current

    print("No")

if __name__ == "__main__":
    main()

