from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder, preserving increasing child order.
        order = []
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                stack.append((v, 1))
                for w in reversed(children[v]):
                    stack.append((w, 0))
            else:
                order.append(v)

        text = ''.join(s[v] for v in order)
        pos = [0] * n
        size = [1] * n
        for i, v in enumerate(order):
            pos[v] = i
            if v != 0:
                size[parent[v]] += size[v]

        # Manacher odd radii.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i-k] == text[i+k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i-k+1, i+k-1

        # Manacher even radii, centered between i-1 and i.
        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i-k-1] == text[i+k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i-k, i+k-1

        answer = [False] * n
        for v in range(n):
            r = pos[v]
            l = r - size[v] + 1
            length = size[v]
            if length & 1:
                answer[v] = d1[(l+r)//2] >= length//2 + 1
            else:
                answer[v] = d2[(l+r+1)//2] >= length//2
        return answer

