from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        pref = 0
        ans = None

        for i, value in enumerate(nums, 1):
            pref += value
            r = i % k

            if mins[r] is not None:
                candidate = pref - mins[r]
                if ans is None or candidate > ans:
                    ans = candidate

            if mins[r] is None or pref < mins[r]:
                mins[r] = pref

        return ans

