import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    last = {}
    best = n + 1
    for i, x in enumerate(data[1:]):
        if x in last:
            best = min(best, i - last[x] + 1)
        last[x] = i
    print(best if best <= n else -1)

if __name__ == "__main__":
    main()

